"""Descriptive report from immutable outputs; no selection/treatment changes."""
import json
from collections import Counter,defaultdict
from pathlib import Path
from research.showdown_fixed_pool_20261013 import experiment as h
from .study import OUT,PRIOR,read,save

def main():
    prep=read(OUT/'prepared.json'); result=read(OUT/'results.json'); coverage=[]; examples=[]
    for run,res in zip(prep['runs'],result['runs']):
        src=read(PRIOR/'inputs'/f"{run['run_id']}.json"); variants=src['run']['constraint_config_json']['strategy_runtime']['showdown_portfolio_policy']['candidate_selection']['ranked_metrics']; labels=defaultdict(set)
        for v in variants: labels[h.roster_id(v)].add(v.get('scenario_id','baseline'))
        roster=[r for r in run['rosters'] if r['current_captain_eligible']]
        support=[r for r in roster if run['annotations'][r['roster_id']]['captain_role_supported'] and run['annotations'][r['roster_id']]['captain_passing_pair_supported'] is not False]
        def key(r):
            a=run['annotations'][r['roster_id']]; cap=a['captain_evidence']; nqb=sum(p['position']=='QB' for p in a['all_player_evidence']); capteam=cap['player_team']; return f"{a['captain_name']} CPT | {capteam} {a['team_counts'][capteam]}-{6-a['team_counts'][capteam]} | {nqb} QB"
        groups=defaultdict(list)
        for r in support: groups[key(r)].append(r['roster_id'])
        armcounts={arm:{k:sum(rid in set(a['eligible_ids']) for rid in ids) for k,ids in groups.items()} for arm,a in res['arms'].items()}
        observed={label:dict(before_quality=sum(label in labels[r['roster_id']] for r in roster),after_both95=sum(label in labels[rid] for rid in res['arms']['both95']['eligible_ids'])) for label in sorted({v for ids in labels.values() for v in ids})}
        # These are supported structural families, not calibrated scenario probabilities.
        extinct=[dict(family=k,before=len(ids),after=0) for k,ids in groups.items() if armcounts['both95'][k]==0]
        savers=Counter(s['status'] for r in roster if r['roster_id'] in res['arms']['neither']['new_eligible_ids'] for s in run['annotations'][r['roster_id']]['salary_savers'])
        coverage.append(dict(slate=run['slate'],captain_supported_structural_families=armcounts,extinguished_supported_structures=extinct,recorded_generation_label_coverage=observed,label_warning='Recorded generation labels overlap physical rosters; labels alone do not prove scenario fitness. Structural groups are descriptive supplemental analysis after main freeze, with no treatment change.',new_roster_saver_occurrences=dict(savers)))
        for arm,a in res['arms'].items():
            for rid in a['pregame_example_ids']:
                row=next(r for r in run['rosters'] if r['roster_id']==rid); an=run['annotations'][rid]
                examples.append(dict(slate=run['slate'],arm=arm,roster_id=rid,rank_alias=row['rank'],mean=row['mean_score'],p90=row['p90_score'],thresholds=run['thresholds'],salary=row['salary'],annotation=an))
    save(OUT/'football_coverage.json',dict(coverage=coverage,examples=examples,all_annotations='prepared.json',retrospective=True,supplemental_after_main_freeze=True))
    text=['# Does the 95% screen remove football-aware upside?', '', 'Yes: it excludes pregame-supported Captain/stack structures as well as low-opportunity constructions. That does not establish reliable joint upside, and removing it did not consistently improve the fixed-size current-score portfolios. Defaults are unchanged. All outcomes were previously inspected: this is retrospective, with no genuinely blinded or held-out conclusion.', '', 'The four arms were frozen before new comparisons. Current scoring, top-four Captain eligibility, original preferences, canonical physical pool, requested-count caps and primary portfolio size stay identical. Both95 baseline exactly reproduces the prior current arm; all six historical physical portfolios/objectives also replay. `prepared.json` freezes annotations before new outcome evaluation, but known outcomes prevent real blindness.', '', '## Fixed-size result', '', 'Entries are average / best actual. Thursday stays at its original achieved four; others stay five. All arms retain cap denominator five.', '', '| Slate | Size | Both95 | Mean95 only | Marginal P90 95 only | Neither |', '|---|---:|---:|---:|---:|---:|']
    for r in result['runs']:
        text.append('| '+r['slate']+' | '+str(r['original_actual_size'])+' | '+' | '.join(f"{r['arms'][arm]['average_actual']:.2f} / {r['arms'][arm]['best_actual']:.2f}" for arm in ['both95','mean95','marginal_p9095','neither'])+' |')
    text+=['', 'P90-only changes none of the five selected portfolios. Neither changes one roster on Thursday (average −10.83) and one on SF–SEA (average +0.05); morning, Sunday night and Monday stay identical. Mean-only raises SF–SEA average by 3.70 and lowers Thursday by 10.83. These are five correlated, already inspected slates; they do not identify a general improvement.', '', '## Coverage and fill', '', 'Eligibility below includes the fixed current Captain shortlist. Newly eligible counts relative to Both95 are in parentheses. Quality and Captain exclusions are separate in results/prepared. All original legal roster and saved preference checks pass.', '', '| Slate | Unique | Both95 eligible | Mean95 | P90 95 | Neither | Max fill Both / Mean / P90 / Neither |', '|---|---:|---:|---:|---:|---:|---|']
    for r in result['runs']:
        text.append('| '+r['slate']+' | '+str(r['unique_rosters'])+' | '+str(len(r['arms']['both95']['eligible_ids']))+' | '+' | '.join(f"{len(r['arms'][a]['eligible_ids'])} (+{len(r['arms'][a]['new_eligible_ids'])})" for a in ['mean95','marginal_p9095','neither'])+' | '+' / '.join(str(r['arms'][a]['capacity']) for a in ['both95','mean95','marginal_p9095','neither'])+' |')
    text+=['', 'Thursday fill capacity grows four→five when the mean gate is removed, with unchanged player/Captain caps. That is separate from the primary outcome comparison, which stays four. No changed-size outcome was computed. Whole-pool gate partition (both / mean-only / P90-only / neither) is TN10/5/22/65, AM12/0/26/27, SF16/10/6/33, SN18/6/13/32, MN32/0/13/12. Captain filtering then narrows these counts. Thus removing quality alone cannot recover a roster whose Captain is outside the unchanged shortlist.', '', '## What football evidence supports', '', 'Every candidate has original canonical-ID-linked role/source/time, game markets, QB/receiver pairs, bring-backs, same-team RB and QB/RB TD dependencies and salary saver evidence in prepared.json. Participation support is deliberately weak: a positive saved projected or lagged workload is not proof of sufficient tournament upside. Null expected workload remains unknown. Backup status and opposing players are not automatic contradictions. No joint target/carry/TD budget can be certified from these snapshots.', '', 'Concrete examples were chosen by pregame current score among newly eligible rosters, not by actual score:', '']
    unique={}
    for e in examples: unique[(e['slate'],e['rank_alias'])]=e
    for slate,rank in [('THURSDAY_NIGHT',28),('SUNDAY_LATE_SF_SEA',25),('MONDAY_NIGHT',68),('SUNDAY_MORNING',24)]:
        e=unique[(slate,rank)]; a=e['annotation']; pnames=[p['name'] for p in a['all_player_evidence'] if p['player_id']!=a['captain_id']]; sav='; '.join(f"{s['evidence']['name']}: projected targets {s['evidence']['projected_targets']}, projected carries {s['evidence']['projected_carries']} ({s['status']})" for s in a['salary_savers']) or 'no FLEX saver <=$3,000'
        text.append(f"- **{slate}, original rank alias {rank}**: {a['captain_name']} CPT; {', '.join(pnames)}. Baseline mean {e['mean']:.2f}, marginal P90 sum {e['p90']:.2f}; floors {e['thresholds']['mean']:.2f}/{e['thresholds']['p90']:.2f}. Captain role is supported; same-team passing pair {a['captain_passing_pair_supported'] if a['captain_passing_pair_supported'] is not None else 'not applicable to RB CPT'}. Salary-saver evidence: {sav}. See exact IDs and sources in football_coverage.json.")
    text+=['', 'Thursday Lamb + Dak is a coherent passing core with opposing TB participation; it fails the marginal-P90 gate despite passing mean. SF–SEA JSN + Darnold is likewise coherent, with modest Cooks/Horton targets rather than verified large workloads. Monday Cook + Allen + Stafford + Coleman/Higbee has two-sided passing participation and a plausible RB-Captain outcome, but Cook competes with Allen/Ty Johnson for BUF TD paths in other variants; the snapshot has no verified joint budget. The morning Pierce saver has only 0.71 projected carries and zero targets: participation is technically supported but tournament ceiling evidence is thin. These distinctions matter more than calling all released rosters football-aware.', '', 'Supplemental structural coverage keeps current Captain eligibility fixed and groups supported Captain roles by own-team roster count and QB count. It is descriptive, added in response to user steering after the main study freeze; no subgroup treatment or outcome tuning. Original generation scenario labels are also preserved across all variants, rather than only the chosen dedup representative. A generated “decisive win” label is not itself evidence of football coherence.', '', '| Slate | Supported structural families before screen | After Both95 | Completely removed families |', '|---|---:|---:|---:|']
    for c in coverage:
        groups=c['captain_supported_structural_families']['neither']; after=c['captain_supported_structural_families']['both95']; text.append(f"| {c['slate']} | {sum(n>0 for n in groups.values())} | {sum(n>0 for n in after.values())} | {len(c['extinguished_supported_structures'])} |")
    text+=['', '## Contest thresholds', '', 'Counts mean reaching frozen field thresholds (ties included), not certified payouts. Full per-contest bands/cash/winner evidence remain in results.json. No cash line is available outside Thursday.', '', '| Slate / contest | Top10 threshold | Both / Mean / P90 / Neither | Cash threshold | Cash counts |', '|---|---:|---|---:|---|']
    for r in result['runs']:
        for cid,c in r['arms']['both95']['contest_attainment'].items():
            top=next(k for k in c if '10' in k); vals=[r['arms'][a]['contest_attainment'][cid] for a in ['both95','mean95','marginal_p9095','neither']]; text.append(f"| {r['slate']} / {cid} | {c[top]['threshold']} | {' / '.join(str(v[top]['count']) for v in vals)} | {c['cash']['threshold']} | {' / '.join(str(v['cash']['count']) for v in vals)} |")
    text+=['', '## Football awareness before quality screening', '', 'The user’s ordering hypothesis is sensible to test prospectively: first establish mathematical legality (salary, roster, canonical identities and user constraints), then certify projection/source reliability, then construct evidence-backed football scenarios and record the user thesis, and finally assess strategic selection tradeoffs. A generic 95% strategic filter should expose its scenario attrition so a coherent thesis is not silently erased. These are separate layers: user gut feel/scenario preferences must not rewrite the model forecast or claim an observed scenario is true.', '', 'Current Showdown code already constructs script/scenario candidates upstream of the final dual screen; discovery also applies earlier 85% mean/90% P90 and later 95% floors. This fixed-pool test establishes downstream attrition, not whether different scenario-first generation would improve results or create missing lineups. Monday SHOOTOUT fits saved ESPN/DK total54.5, LAR−3.5, implied29/25.5, observed pregame. Original 9c07a5bd Captain preference was WR/RB; current retrospective shortlist remains constrained by that saved preference. Later 06a274d6 Allen/Stafford/Puka/Kyren selections cannot be conflated with this original pool.', '', '## Classic applicability', '', 'The tested dual95 selector is the Showdown portfolio path: optimizer.py defines portfolio_v3 from the Showdown strategy at line7173, applies earlier floors at7341 and calls select_showdown_portfolio at7620. Classic GPP branches at8462 through run_gpp_pipeline/execute_strategy_contract and classic_small_field at8734. Its own family/overlap/objective tradeoffs (classic_small_field.py1642, classic_portfolio_policy.py84) differ. The same strategic-filter concern can be investigated, but this Showdown effect cannot be assumed for Classic. Historical Classic pools have only five saved candidates/all selected, so they cannot estimate omitted candidate opportunity.', '', '## Limits and next test', '', 'Keep defaults unchanged. Run a prospective pregame-certified comparison on uninspected slates, freezing candidate pool, source timestamps, model/code, preferences, scenario thesis, caps and size. Retain these four screen arms (or prechoose both95 versus neither if budget is limited); record scenario support/coverage before outcomes, unknown saver roles, underfill and contest attainment separately. A separate generation experiment would be needed to test scenario-first/gut-feel candidate construction. Missing contemporaneous executable hash and completion attestation, five inspected pools, correlated rosters and absent joint-opportunity budgets bound this study.', '', 'Commands (repo root):', '', '```sh', '.venv/bin/python -B -m research.showdown_quality_screen_20261013.study freeze', '.venv/bin/python -B -m research.showdown_quality_screen_20261013.study evaluate', '.venv/bin/python -B -m research.showdown_quality_screen_20261013.study evaluate', '.venv/bin/python -B -m research.showdown_quality_screen_20261013.study validate', '.venv/bin/python -B -m research.showdown_quality_screen_20261013.report', '```', '', 'freeze.json pins original source/report/code hashes, prior harness, annotations/spec and CBC binary. study.py reuses verified prior harness without writing prior artifacts. validation.json records focused checks and repeated identical result bytes. Only this new research directory was written. No application tests or expensive simulation were needed for this offline analysis.']
    (OUT/'README.md').write_text('\n'.join(text)+'\n')
    save(OUT/'report_manifest.json',dict(report_code_sha256=h.sha(OUT/'report.py'),football_coverage_sha256=h.sha(OUT/'football_coverage.json'),readme_sha256=h.sha(OUT/'README.md'),main_results_sha256=h.sha(OUT/'results.json'),main_freeze_sha256=h.sha(OUT/'freeze.json'),supplemental_structure_analysis_after_freeze=True))
    for c in coverage: print(c['slate'],c['extinguished_supported_structures'],c['recorded_generation_label_coverage'])
if __name__=='__main__': main()
